-- DSU-CFCS | SYNTHETIC DEMO ONLY | Academic year 2026-2027
-- Run this entire script ONCE in a new, empty PostgreSQL 17 database.
-- It contains generated test fixtures, not records copied from the running preview.
-- No passwords, API tokens, login sessions or university records are included.
DO $cfcs_demo_setup$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(740128);
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
             WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S','f')
               AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_depend d WHERE d.classid='pg_catalog.pg_class'::pg_catalog.regclass AND d.objid=c.oid AND d.deptype='e')) THEN
    RAISE EXCEPTION 'Stop: the public schema is not empty. Select a fresh demo database. Nothing was imported.';
  END IF;

PERFORM pg_catalog.set_config('search_path', '', true);

CREATE FUNCTION public.protect_audit_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN RAISE EXCEPTION 'Academic audit history is append-only'; END $$;

CREATE TABLE public.academic_audit_logs (
    id bigint NOT NULL,
    actor_id bigint,
    action text NOT NULL,
    entity text NOT NULL,
    entity_id bigint,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    recorded_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE public.academic_audit_logs ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.academic_audit_logs_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.academic_exceptions (
    id bigint NOT NULL,
    student_id bigint NOT NULL,
    course_id bigint,
    kind text NOT NULL,
    reason text NOT NULL,
    evidence text NOT NULL,
    requested_by bigint NOT NULL,
    authority text NOT NULL,
    status text NOT NULL,
    extra_credits numeric DEFAULT 0 NOT NULL,
    academic_year_id bigint NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_by bigint,
    remarks text,
    decided_at timestamp with time zone,
    CONSTRAINT academic_exceptions_extra_credits_check CHECK ((extra_credits >= (0)::numeric)),
    CONSTRAINT academic_exceptions_kind_check CHECK ((kind = ANY (ARRAY['Conditional prerequisite'::text, 'Credit overload'::text, 'Course equivalence'::text, 'Special offering'::text, 'Timetable'::text, 'Academic progression'::text, 'Attendance exception'::text]))),
    CONSTRAINT academic_exceptions_status_check CHECK ((status = ANY (ARRAY['Pending'::text, 'Approved'::text, 'Rejected'::text])))
);

ALTER TABLE public.academic_exceptions ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.academic_exceptions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

