);

CREATE TABLE public.timetable_slots (
    id bigint NOT NULL,
    section_id bigint NOT NULL,
    room_id bigint NOT NULL,
    weekday smallint NOT NULL,
    starts integer NOT NULL,
    ends integer NOT NULL,
    kind text NOT NULL,
    CONSTRAINT timetable_slots_check CHECK (((starts >= 0) AND (ends <= 1440) AND (starts < ends))),
    CONSTRAINT timetable_slots_kind_check CHECK ((kind = ANY (ARRAY['Theory'::text, 'Tutorial'::text, 'Practical'::text]))),
    CONSTRAINT timetable_slots_weekday_check CHECK (((weekday >= 1) AND (weekday <= 7)))
);

